ALTER TABLE users ADD COLUMN role varchar(20) NOT NULL DEFAULT 'user', ADD COLUMN suspended boolean NOT NULL DEFAULT false, ADD COLUMN email_verified boolean NOT NULL DEFAULT false, ADD COLUMN legal_version varchar(50), ADD COLUMN legal_accepted_at datetime;
CREATE TABLE households (id varchar(36) PRIMARY KEY, owner_id varchar(36) NOT NULL, name varchar(200) NOT NULL, FOREIGN KEY(owner_id) REFERENCES users(id));
CREATE TABLE household_members (household_id varchar(36) NOT NULL,user_id varchar(36) NOT NULL, PRIMARY KEY(household_id,user_id), FOREIGN KEY(household_id) REFERENCES households(id) ON DELETE CASCADE, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE household_invitations (id varchar(36) PRIMARY KEY,household_id varchar(36) NOT NULL,token_hash char(64) NOT NULL UNIQUE,email varchar(254),expires_at bigint NOT NULL,used_at bigint,FOREIGN KEY(household_id) REFERENCES households(id) ON DELETE CASCADE);
CREATE TABLE records (id varchar(36) PRIMARY KEY,kind varchar(30) NOT NULL,user_id varchar(36) NOT NULL,household_id varchar(36),data JSON NOT NULL,revision int NOT NULL DEFAULT 1,created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(household_id) REFERENCES households(id) ON DELETE CASCADE,INDEX(user_id,kind),INDEX(household_id,kind));
CREATE TABLE record_links (source_id varchar(36) NOT NULL,target_id varchar(36) NOT NULL,PRIMARY KEY(source_id,target_id),FOREIGN KEY(source_id) REFERENCES records(id) ON DELETE CASCADE,FOREIGN KEY(target_id) REFERENCES records(id) ON DELETE RESTRICT);
CREATE TABLE account_tokens (token_hash char(64) PRIMARY KEY,user_id varchar(36) NOT NULL,purpose varchar(20) NOT NULL,expires_at bigint NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE audit_logs (id varchar(36) PRIMARY KEY,user_id varchar(36),event varchar(100) NOT NULL,created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE settings (id varchar(50) PRIMARY KEY,data JSON NOT NULL);
INSERT INTO settings(id,data) VALUES ('registration',JSON_OBJECT('enabled',true,'invitationOnly',false)),('general',JSON_OBJECT('name','Mijovia'));
CREATE TABLE signup_invitations (token_hash char(64) PRIMARY KEY,expires_at bigint NOT NULL,used_at bigint);
